import type { Path as PathService, PlatformError } from "effect";

import { Effect, FileSystem, Option, Path, Schema } from "effect";

import type { ApiContribution } from "../../../../contracts/internal/src/author-schemas/api.ts";
import type { FeatureLoaderError } from "../../../../contracts/internal/src/errors.ts";
import type { ResolvedFeature } from "../../../../engine/features/src/feature-loader-types.ts";

import { ApiContributionSchema } from "../../../../contracts/internal/src/author-schemas/api.ts";
import { discoverFeatures } from "../../../../engine/features/src/feature-loader.ts";

const GENERATED_FILE_BANNER = `// Generated by Ori; do not edit.
// This file is refreshed from the workspace feature modules.
`;

/**
 * One workspace feature that contributed a decodable `api`, paired with the
 * module specifier the generated `.ori/*.d.ts` will `import(...)` it by.
 */
interface FeatureApiSource {
  readonly api: ApiContribution;
  readonly featureId: string;
  readonly modulePath: string;
}

const featureApiSources = (input: {
  readonly features: readonly ResolvedFeature[];
  readonly featuresRoot: string;
  readonly path: PathService.Path;
  readonly projectRoot: string;
}): readonly FeatureApiSource[] =>
  input.features.flatMap((feature) => {
    const apiContribution = feature.contributions.find(
      (contribution) => contribution.entryKey === "api"
    );
    const decodedApi = Schema.decodeUnknownOption(ApiContributionSchema)(
      apiContribution?.moduleNamespace?.api
    );
    const api = Option.getOrUndefined(decodedApi);
    if (api === undefined) {
      return [];
    }
    const modulePath = input.path
      .relative(
        input.path.join(input.projectRoot, ".ori"),
        input.path.join(input.featuresRoot, feature.id, "feature.ts")
      )
      .replace(/\.ts$/u, "")
      .replaceAll(input.path.sep, "/");
    return [
      {
        api,
        featureId: feature.id,
        modulePath: modulePath.startsWith(".") ? modulePath : `./${modulePath}`,
      },
    ];
  });

/**
 * Render one `declare module "ori"` augmentation file: the generated banner,
 * the caller's conditional-type helper, and one interface whose members come
 * from `toDeclarationLines`. Entries are sorted by feature id so the output is
 * stable across feature-discovery order. A file with no members omits the
 * helper entirely, leaving an empty interface.
 */
const renderFeatureDeclaration = <
  A extends { readonly featureId: string },
>(input: {
  readonly entries: readonly A[];
  readonly interfaceName: string;
  readonly toDeclarationLines: (entry: A) => readonly string[];
  readonly typeHelper: string;
}): string => {
  const lines = input.entries
    .toSorted((left, right) => left.featureId.localeCompare(right.featureId))
    .flatMap((entry) => input.toDeclarationLines(entry));
  const helper =
    lines.length === 0
      ? ""
      : `\n  ${input.typeHelper.replaceAll("\n", "\n  ")}`;
  return `${GENERATED_FILE_BANNER}
declare module "ori" {${helper}
  interface ${input.interfaceName} {${lines.length === 0 ? "" : `\n${lines.join("\n")}\n  `}}
}
`;
};

/**
 * Discover the workspace features, render `fileName` from their `api`
 * contributions, and write it under `.ori/` only when the content changed, so
 * a no-op refresh does not churn the file's mtime.
 */
const writeFeatureDeclaration = Effect.fn(
  "ProjectInit.writeFeatureDeclaration"
)(function* (input: {
  readonly featuresRoot: string;
  readonly fileName: string;
  readonly projectRoot: string;
  readonly render: (sources: readonly FeatureApiSource[]) => string;
}): Effect.fn.Return<
  void,
  FeatureLoaderError | PlatformError.PlatformError,
  FileSystem.FileSystem | Path.Path
> {
  const fs = yield* FileSystem.FileSystem;
  const path = yield* Path.Path;
  const { features } = yield* discoverFeatures(input.featuresRoot);
  const content = input.render(
    featureApiSources({
      features,
      featuresRoot: input.featuresRoot,
      path,
      projectRoot: input.projectRoot,
    })
  );
  const target = path.join(input.projectRoot, ".ori", input.fileName);
  const current = yield* fs.readFileString(target).pipe(Effect.option);
  if (Option.getOrUndefined(current) !== content) {
    yield* fs.makeDirectory(path.dirname(target), { recursive: true });
    yield* fs.writeFileString(target, content);
  }
});

export { renderFeatureDeclaration, writeFeatureDeclaration };
export type { FeatureApiSource };
